def script1():
    go_to(0, -140)
    正解 = 7
    予想 = int(input("1から10の数は？"))
    # 予想が正解とちがうあいだ、くり返す
    #   予想が小さければ「もっと大きい」、大きければ「もっと小さい」と1秒言う
    #   そのあと、もう一度質問して予想に入れる
