@when_flag_clicked
def script1():
    go_to(0, -140)
    問題 = ["2 + 3 は？", "4 × 5 は？", "10 - 7 は？"]
    正解 = ["5", "20", "3"]
    点数 = 0
    # for を使って3問出す。正解なら点数を1ふやす
    for i in range(3):
        答え = input(問題[i])
        if 答え == 正解[i]:
            点数 = 点数 + 1
    say_for("点数は" + str(点数) + "点", 2)
